INSERT INTO cms_topic (`id`,`member_id`,`topic_type`,`product_type`,`circle_theme_code`,`source_template_topic_id`,`circle_reviewed_at`,`complete_rule_json`,`route_mode`,`route_graph_json`,`config_version`,`published_route_graph_json`,`published_config_version`,`roam_referral_enabled`,`topic_id`,`source_topic_id`,`name`,`subtitle`,`description`,`address_name`,`total_time`,`total_mileage`,`location_count`,`template_count`,`start_date`,`end_date`,`img_url`,`img_arr`,`category_ids`,`status`,`reason`,`user_status`,`merchant_status`,`open_club_pool`,`merchant_sign_up_start_date`,`merchant_sign_up_end_date`,`recruit_deadline`,`sale_end_at`,`selling_started_at`,`recruit_extend_count`,`lifecycle`,`del_flag`,`is_sync`,`is_recommend`,`check_status`,`is_settlement`,`create_by`,`create_time`,`update_by`,`update_time`,`publish_mode`,`club_id`,`self_play`,`self_play_price`,`self_play_quota`,`xp_budget`,`finish_medal_name`,`finish_medal_img`,`complete_reward_coupon_id`,`audio_url`,`audio_duration`,`is_draft`,`is_template`,`beta_flag`,`fee_platform_rate`,`fee_guarantee_base_rate`,`fee_guarantee_step_rate`,`fee_guarantee_max_merchant`,`team_mode`,`team_max_members`,`game_module_config_json`,`club_coop_open`,`club_pinned`,`club_member_only`,`journey_rules_json`,`journey_story_json`) VALUES (990059,100000,1,1,NULL,NULL,NULL,NULL,'LINEAR',NULL,1,NULL,1,0,NULL,NULL,'预制人生 · 四站试玩版','从人民广场出发,走完一个被预制的人','你在城市模型里出生,在人民广场站学会说「收到」,在第一百货看见被高楼切开的天,最后走到南京东路尽头那道看不见的边界。4 站 5 个 GPS 点位,只走公共空间:不入店、不消费、不要求任何商家或工作人员参与。本主题是内部试玩版,不进公开列表;持 0 元自玩通行证即可开走。梦与照片留在你自己的记录里。','上海市黄浦区人民广场片区',7200,'2.00',5,5,NULL,NULL,'https://oss.example.com/it-test.png',NULL,'0',1,NULL,1,0,0,NULL,NULL,NULL,NULL,NULL,0,0,0,0,0,0,0,'seed_prefab_life_20260918','2026-09-18T21:52:47','seed_prefab_life_20260918','2026-09-18T21:53:39','pro',NULL,1,'0.00',NULL,3000,'预制人生 · 第一次偏离',NULL,NULL,NULL,NULL,0,1,0,NULL,NULL,NULL,NULL,0,4,NULL,1,0,0,NULL,NULL);
INSERT INTO cms_topic_chapter (`id`,`topic_id`,`name`,`description`,`img_arr`,`total_time`,`total_mileage`,`location_count`,`template_count`,`sort_id`,`create_by`,`create_time`,`update_by`,`update_time`,`category`,`category_id`,`recruit_enabled`,`finish_time`,`perk_min_value`,`max_merchant`,`required`,`need_group`,`terms_mode`,`circle_candidate_code`,`circle_role`,`circle_policy`,`circle_enabled`,`max_per_head_fee`,`allowed_validation_methods`,`max_node_xp`,`blocks`,`atmosphere_preset`,`audio_url`) VALUES (211,990059,'第一章 · 出生','你在城市模型里醒来。先登记身份,再上第一课:什么叫标准答案。',NULL,0,NULL,1,1,1,'seed_prefab_life_20260918','2026-09-18T21:52:48','seed_prefab_life_20260918','2026-09-18T21:53:39',NULL,NULL,0,NULL,NULL,0,1,NULL,'TRAFFIC',NULL,NULL,NULL,1,NULL,NULL,NULL,'[{"type":"text","content":"你在一间摆满城市模型的房间里醒来。系统先让你登记:你叫什么,你做什么,你信不信标准答案。老师敲了敲讲台:「{name|那个人},来,站起来,你来回答一下?」"},{"type":"node","nodeId":192},{"type":"dream","key":"p1_dream","images":[{"url":"https://oss.example.com/it-test.png','DEFAULT',NULL);
INSERT INTO cms_topic_chapter (`id`,`topic_id`,`name`,`description`,`img_arr`,`total_time`,`total_mileage`,`location_count`,`template_count`,`sort_id`,`create_by`,`create_time`,`update_by`,`update_time`,`category`,`category_id`,`recruit_enabled`,`finish_time`,`perk_min_value`,`max_merchant`,`required`,`need_group`,`terms_mode`,`circle_candidate_code`,`circle_role`,`circle_policy`,`circle_enabled`,`max_per_head_fee`,`allowed_validation_methods`,`max_node_xp`,`blocks`,`atmosphere_preset`,`audio_url`) VALUES (212,990059,'第二章 · 工作','人民广场站的换乘通道和会议室,是同一套系统的两个切面。',NULL,0,NULL,2,2,2,'seed_prefab_life_20260918','2026-09-18T21:52:48','seed_prefab_life_20260918','2026-09-18T21:53:39',NULL,NULL,0,NULL,NULL,0,1,NULL,'TRAFFIC',NULL,NULL,NULL,1,NULL,NULL,NULL,'[{"type":"node","nodeId":193},{"type":"text","content":"换乘通道里每个人都走得很快。广播念着同一个动词,人群替你做了选择。无论是{job|上班族}还是别的身份,系统都用同一个动词管理。老板把方案推到一边:「这个方案……先放一放。」{name|那个人},你听见自己在会议室的安静里开口。"},{"type":"node","nodeId":194},{"type":"dream","key":"p2_dream","images":[{"url":"https://oss.example.com/it-test.png','DEFAULT',NULL);
INSERT INTO cms_topic_chapter (`id`,`topic_id`,`name`,`description`,`img_arr`,`total_time`,`total_mileage`,`location_count`,`template_count`,`sort_id`,`create_by`,`create_time`,`update_by`,`update_time`,`category`,`category_id`,`recruit_enabled`,`finish_time`,`perk_min_value`,`max_merchant`,`required`,`need_group`,`terms_mode`,`circle_candidate_code`,`circle_role`,`circle_policy`,`circle_enabled`,`max_per_head_fee`,`allowed_validation_methods`,`max_node_xp`,`blocks`,`atmosphere_preset`,`audio_url`) VALUES (213,990059,'第三章 · 命数','第一百货的楼梯间里,小周问你:那又怎么样呢?',NULL,0,NULL,1,1,3,'seed_prefab_life_20260918','2026-09-18T21:52:48','seed_prefab_life_20260918','2026-09-18T21:53:39',NULL,NULL,0,NULL,NULL,0,1,NULL,'TRAFFIC',NULL,NULL,NULL,1,NULL,NULL,NULL,'[{"type":"text","content":"第一百货的楼梯间里,小周点了一根烟。「那又怎么样呢?」他问,「真的世界里,难道就不用打卡了吗?」你看向他身后那道被高楼切开的天。"},{"type":"node","nodeId":195},{"type":"dream","key":"p3_dream","images":[{"url":"https://oss.example.com/it-test.png','DEFAULT',NULL);
